<?php
require 'config/auth.php';require 'config/db.php';require_roles(['admin']);require_once 'config/financial.php';require_once 'config/periods.php';
$year=(int)($_GET['year']??$_POST['year']??fiscal_year_for_date());$error='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 try{begin_financial_transaction($conn);$unit=(int)($_POST['unit_id']??0);$month=(int)($_POST['month']??0);$reason=trim($_POST['reason']??'');
 if(($_POST['action']??'')==='close')period_close($conn,$unit,$year,$month,$reason);
 elseif(($_POST['action']??'')==='reopen')period_reopen($conn,$unit,$year,$month,$reason);
 else throw new RuntimeException('ไม่พบคำสั่ง');$conn->commit();header('Location: fiscal_periods.php?year='.$year.'&saved=1');exit;
 }catch(Throwable $e){$conn->rollback();$error=operation_error($e);}
}
$units=$conn->query('SELECT * FROM units ORDER BY unit_code')->fetch_all(MYSQLI_ASSOC);$stmt=$conn->prepare('SELECT fp.*,u.unit_code FROM fiscal_periods fp JOIN units u ON u.id=fp.unit_id WHERE fp.fiscal_year=? AND (fp.closed=1 OR fp.closed_at IS NOT NULL) ORDER BY fp.unit_id,fp.period_month');$stmt->bind_param('i',$year);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
?>
<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>ปิดงวดบัญชี</title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php require 'template/nav.php';?><main class="container"><section class="panel"><h1 class="page-title">ปิดงวด / ปีงบประมาณ</h1><p>ปิดแล้วจะป้องกันการเปลี่ยนรายการในงวดนั้น เปิดใหม่ได้เฉพาะผู้ดูแลพร้อมเหตุผล ประวัติและสำเนาตอนปิดยังคงอยู่</p><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="alert alert-success">บันทึกสถานะงวดแล้ว</div><?php endif;?><form method="post"><?=csrf_field()?><?=request_field()?><div class="form-grid form-grid-2"><label>ปีงบประมาณ</label><input type="number" name="year" value="<?=$year?>" required><label>หน่วย</label><select name="unit_id" required><option value="">-- เลือกหน่วย --</option><?php foreach($units as $unit):?><option value="<?=$unit['id']?>"><?=htmlspecialchars($unit['unit_code'].' '.$unit['unit_name'])?></option><?php endforeach;?></select><label>งวด</label><select name="month"><option value="0">ทั้งปีงบประมาณ</option><?php foreach([10=>'ตุลาคม',11=>'พฤศจิกายน',12=>'ธันวาคม',1=>'มกราคม',2=>'กุมภาพันธ์',3=>'มีนาคม',4=>'เมษายน',5=>'พฤษภาคม',6=>'มิถุนายน',7=>'กรกฎาคม',8=>'สิงหาคม',9=>'กันยายน'] as $number=>$name):?><option value="<?=$number?>"><?=$name?></option><?php endforeach;?></select><label>การดำเนินการ</label><select name="action"><option value="close">ปิดงวด</option><option value="reopen">เปิดงวดใหม่</option></select><label>เหตุผล / ผลตรวจยอด</label><textarea name="reason" minlength="5" maxlength="255" required></textarea></div><button class="btn btn-primary">ยืนยัน</button></form></section><section class="panel"><div class="toolbar"><a class="btn btn-outline" href="reconciliation.php?year=<?=$year?>">กระทบยอด / ผูกข้อมูลเดิม</a><a class="btn btn-outline" href="document_archive.php?year=<?=$year?>">สำเนาตอนปิดงวด</a></div><table><tr><th>หน่วย</th><th>งวด</th><th>สถานะ</th><th>วันเวลาปิด</th><th>เหตุผลล่าสุด</th></tr><?php foreach($rows as $row):?><tr><td><?=htmlspecialchars($row['unit_code'])?></td><td><?=$row['period_month']?:'ทั้งปี'?></td><td><?=$row['closed']?'ปิดแล้ว':'เปิดใหม่แล้ว'?></td><td><?=htmlspecialchars($row['closed_at'])?></td><td><?=htmlspecialchars($row['reason'])?></td></tr><?php endforeach;?></table></section></main></body></html>
